// Frozen abstract cores. Seeding makes ZERO LLM calls so it cannot fail on stage.
// Every motion here is one the team has actually competed on (original Chinese motion
// and source file kept in `source`, so any result can be traced back to real material).
// Shape: { motion, source, output: { abstract_core, value_clash, burdens, stakeholders, core_mechanism } }
// To regenerate uniformly, run workflow 2 and paste its output here.
const skeletons = [
  {
    motion: 'This house believes that the public deconstruction of the norm \'do not speak ill of the dead\' is a bad thing',
    source: 'Case notes and rebuttal file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether an openly held practice should be condemned because a minority abuse it, or judged by the principle it serves, given that extending any entitlement to everyone makes some misuse inevitable.',
      value_clash: 'Judging an open practice by its underlying principle versus judging it by its worst users.',
      burdens: 'The proposition must show the abuse is the practice\'s dominant real form rather than a fringe tail; the opposition must show the principle is sound and that predictable misuse is the price of any entitlement held by everyone.',
      stakeholders: 'Those the practice is exercised upon, ordinary participants, bad-faith participants, and the collective that sets the norm.',
      core_mechanism: 'Any entitlement extended to everyone will be used badly by some, so the question is whether that predictable extreme tail redefines the practice or is simply the cost of the practice existing at all.',
    },
  },
  {
    motion: 'This house believes radical feminism does more good than harm for gender equality',
    source: 'Attack and defence file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether a collective pursuing a legitimate end through disruptive, norm-breaking means contributes net positively, when the extremity that forces attention is the same feature opponents use to discredit the whole.',
      value_clash: 'The necessity of a disruptive vanguard versus the backlash and delegitimisation it generates.',
      burdens: 'The proposition must show that an ignored claim enters public view only when some actors break normal channels; the opposition must show the extreme wing costs more allies than the attention is worth.',
      stakeholders: 'The moderate majority under the label, the disruptive minority, undecided observers, and opponents of the claim.',
      core_mechanism: 'A collective is judged by its most extreme participants, and the disruption that makes a claim visible is the same behaviour used to discredit everyone under the label, so visibility and delegitimisation arrive together.',
    },
  },
  {
    motion: 'This house believes social media brings people closer together',
    source: 'Attack and defence file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether an intermediating system produces genuine closeness between individuals, or produces the appearance of contact while the conditions required for real understanding are quietly eroded.',
      value_clash: 'Access and frequency of contact versus depth and authenticity of connection.',
      burdens: 'The proposition must show the contact it enables converts into relationships that would not otherwise exist, especially for the isolated; the opposition must show it substitutes for deeper contact rather than adding to it.',
      stakeholders: 'Isolated individuals, ordinary participants, the operators of the intermediating system, and the communities it displaces.',
      core_mechanism: 'Lowering the cost of contact multiplies interactions but changes what an interaction is, so more connection can coexist with less understanding.',
    },
  },
  {
    motion: 'This house believes the spread of AI counselling should be treated with caution',
    source: 'First speech and case file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether the rapid spread of an immature substitute into a high-stakes domain should be restrained, when its accessibility is real but its failures are catastrophic and invisible to the person relying on it.',
      value_clash: 'Expanding access to an unmet need versus the irreversibility of failure in a high-stakes domain.',
      burdens: 'The proposition must show the substitute fails in ways the user cannot detect and that failure falls on the most vulnerable; the opposition must show the counterfactual is no help at all rather than expert help.',
      stakeholders: 'Those relying on the substitute in crisis, the qualified providers displaced, the supplier, and the regulator.',
      core_mechanism: 'A cheap substitute reaches those the expert system never reached, but the user cannot tell when it is wrong, and in this domain being wrong is not recoverable.',
    },
  },
  {
    motion: 'This house believes manufacturer self-certification of aircraft safety is a developmental trend rather than a stopgap',
    source: 'Prep file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether delegating verification to the party being verified is a genuine evolution of oversight or a compensation for a supervisor that can no longer keep pace, given that incentives diverge exactly when verification matters most.',
      value_clash: 'Efficiency and expertise of the insider versus independence of the verifier.',
      burdens: 'The proposition must show expertise has migrated irreversibly to the producer and oversight can be redesigned around that; the opposition must show the arrangement exists from under-resourcing and fails in the cases it most needs to catch.',
      stakeholders: 'Those exposed to the risk, the producing party, the supervising body, and insiders who raise concerns.',
      core_mechanism: 'The party with the deepest knowledge is also the party with the strongest interest in a favourable result, so competence and impartiality pull in opposite directions.',
    },
  },
  {
    motion: 'This house believes restaurants\' use of pre-made meals increases consumer welfare',
    source: 'Evidence and prep file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether industrial standardisation of a craft-based provision increases welfare, when it raises the floor and lowers cost but removes the upper range of quality and leaves the recipient unable to know what they are receiving.',
      value_clash: 'Raising the floor for everyone versus informed choice and the loss of the ceiling.',
      burdens: 'The proposition must show the floor genuinely rises for the majority and the risk removed exceeds the quality forgone; the opposition must show the recipient pays for one thing and receives another, and that the lost information is itself the harm.',
      stakeholders: 'Recipients of the provision, the providers, the industrial suppliers, and the skilled practitioners displaced.',
      core_mechanism: 'Standardisation compresses variance in both directions, so the worst outcomes improve and the best disappear, and the recipient\'s ability to tell which they are getting disappears with it.',
    },
  },
  {
    motion: 'This house believes young people should keep escalating their credentials as credentials devalue',
    source: 'First speech and evidence file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether an individually rational decision to escalate remains rational once everyone makes it, when the return on escalation falls as participation rises and the resource spent cannot be recovered.',
      value_clash: 'Individual competitive advantage versus collective zero-sum exhaustion.',
      burdens: 'The proposition must show the escalation still yields a real relative advantage to whoever makes it; the opposition must show the marginal return has collapsed and the escalation costs an irreplaceable window elsewhere.',
      stakeholders: 'Those who escalate, those who decline, the institutions selecting between them, and those financing the escalation.',
      core_mechanism: 'When a positional good is chased by everyone, effort rises while relative position stays fixed, so the rational individual move makes every participant worse off and destroys the scarcity that made the good valuable.',
    },
  },
  {
    motion: 'This house would fund digital consciousness upload rather than physical survival for all',
    source: 'Prep file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether a collective facing an existential constraint should divide finite means between two incompatible routes, when the more attractive route cannot be scaled to everyone and rationing access destroys the cooperation the other route requires.',
      value_clash: 'Pursuing the more desirable outcome for some versus preserving a route that can include everyone.',
      burdens: 'The proposition must show the attractive route is reachable in time and access can be allocated without collapsing cooperation; the opposition must show exclusion converts the excluded from contributors into opponents.',
      stakeholders: 'The excluded majority, those granted access, those allocating access, and the generations that follow.',
      core_mechanism: 'An option only a few can take does not merely split the budget; it removes the excluded majority\'s reason to sustain the alternative, so the division is destructive rather than proportional.',
    },
  },
  {
    motion: 'This house believes developing nations should prioritise economic growth over environmental protection',
    source: 'Attack and defence file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether a collective facing urgent present deprivation should prioritise immediate material improvement over a diffuse, irreversible long-horizon harm borne disproportionately by those who did not cause it.',
      value_clash: 'Present urgency of the deprived versus irreversibility of long-horizon harm.',
      burdens: 'The proposition must show the deprivation is severe enough that deferral is not available and capacity to repair follows improvement; the opposition must show the harm crosses a threshold beyond which repair is impossible.',
      stakeholders: 'The currently deprived, those who follow them, the collectives that already improved, and those bearing the harm without causing it.',
      core_mechanism: 'The costs fall in different periods and on different parties, so what is framed as one actor\'s tradeoff is in fact a transfer from one group to another.',
    },
  },
  {
    motion: 'This house would make voting compulsory',
    source: 'Prep file (round debated in Chinese)',
    output: {
      abstract_core: 'Whether participation in a collective decision should be a protected choice or an enforced duty, when leaving it optional systematically silences exactly the groups the decision most affects.',
      value_clash: 'Individual autonomy including the right to abstain versus the representativeness of the collective outcome.',
      burdens: 'The proposition must show voluntary participation filters by resources and confidence, entrenching those already heard; the opposition must show compelled participation without engagement degrades the decision and that autonomy includes refusal.',
      stakeholders: 'Those who rarely participate, habitual participants, those who organise the decision, and the collective bound by it.',
      core_mechanism: 'Voluntary participation is not neutral because it filters by resources and confidence, so a formally equal entitlement produces substantively unequal representation.',
    },
  },
  {
    motion: 'This house believes that for young people, who they want to become matters more than who they refuse to become',
    source: 'Both sides\' prep files (round debated in Chinese)',
    output: {
      abstract_core: 'Whether an individual is better guided by an aspirational ceiling they move toward or a prohibitive floor they refuse to fall below, when the first gives direction but is easily inherited unexamined and the second gives resistance but no destination.',
      value_clash: 'Direction and drive from a positive ideal versus authorship and resistance from a negative boundary.',
      burdens: 'The proposition must show that without a destination a life has only edges and drive cannot come from refusal alone; the opposition must show positive goals are the easiest thing to borrow from the surrounding order, so only refusal secures authorship.',
      stakeholders: 'The individual choosing, those who set the prevailing script, and those who follow it unexamined.',
      core_mechanism: 'A positive goal is easy to adopt unexamined from the surrounding order while a refusal is hard to borrow, but a refusal alone defines the edges of a life without filling its centre.',
    },
  },
  {
    motion: 'This house believes the passage of time is poison to love',
    source: 'First speech (round debated in Chinese)',
    output: {
      abstract_core: 'Whether duration degrades a bond or is the only process capable of producing the qualities the bond is said to consist of, which turns the test into a dispute over what the thing being tested actually is.',
      value_clash: 'Intensity and novelty as the essence of the bond versus depth and reliability built only by duration.',
      burdens: 'The proposition must show what is lost over time is constitutive of the thing rather than incidental; the opposition must show anything duration can dissolve was never the thing in question, so the test identifies rather than destroys.',
      stakeholders: 'Both parties to the bond, those who leave early, and those who remain.',
      core_mechanism: 'If the bond is defined by early intensity then duration destroys it, and if it is defined by understanding and reliability then duration is the only thing that can build it, so the disagreement is definitional rather than empirical.',
    },
  },
];

return skeletons.map((s) => ({ json: s }));

// Tolerant JSON extraction. Reasoning models emit <think> blocks, markdown
// fences and stray prose; none of that should be able to break the run.
const clean = (raw) => String(raw ?? '')
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/<\/?think>/gi, '')
  .replace(/```[a-z]*/gi, '')
  .replace(/```/g, '');

const flatten = (v) => {
  if (v == null) return '';
  if (Array.isArray(v)) return v.map(flatten).filter(Boolean).join(', ');
  if (typeof v === 'object') return Object.values(v).map(flatten).filter(Boolean).join(' ');
  return String(v);
};

return $input.all().map((item) => {
  const text = clean(item.json.text ?? item.json.output ?? item.json.response ?? '');
  let obj = {};
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try {
      obj = JSON.parse(text.slice(start, end + 1));
    } catch (e) {
      try {
        obj = JSON.parse(text.slice(start, end + 1).replace(/,\s*([}\]])/g, '$1'));
      } catch (e2) {
        obj = {};
      }
    }
  }
  return { json: {
    output: {
      abstract_core: flatten(obj.abstract_core),
      value_clash: flatten(obj.value_clash),
      burdens: flatten(obj.burdens),
      stakeholders: flatten(obj.stakeholders),
      core_mechanism: flatten(obj.core_mechanism),
    },
    parse_ok: !!flatten(obj.abstract_core),
    raw_preview: text.slice(0, 300),
  } };
});
